// Pixel scenery: all shapes, sprites and textures are original and generated locally.
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(Math.round(x),Math.round(y),rx,ry,0,0,Math.PI*2);ctx.fill()}
function poly(points,c){ctx.fillStyle=c;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill()}
function hash(n){let v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)}
function puff(x,y,s,c){rect(x,y,48*s,13*s,c);rect(x+9*s,y-7*s,29*s,25*s,c);rect(x+18*s,y-12*s,13*s,28*s,c)}
