function flower(x,y,i){let c=['#edc488','#db9f92','#ebe2ad'][i%3];rect(x,y-8,2,9,'#4d8050');rect(x-3,y-10,7,3,c);rect(x-1,y-12,3,7,c);rect(x,y-9,2,2,'#f7e3a1')}
function grassPlatform(p,ground=false){let depth=ground?80:31;rect(p.x,p.y+5,p.w,depth,'#82775a');rect(p.x,p.y+9,p.w,depth-8,'#9b8560');rect(p.x,p.y+14,p.w,4,'#b29a6b');for(let i=0;i<p.w/14;i++){let xx=p.x+i*14,yy=p.y+20+hash(i+p.x)*Math.max(8,depth-28);rect(xx,yy,5+hash(i)*8,4,'#776c50');rect(xx+3,yy-2,4,2,'#c2a478')}rect(p.x-3,p.y-4,p.w+6,8,'#427548');rect(p.x-3,p.y-6,p.w+6,4,'#a8bd6c');rect(p.x,p.y-2,p.w,4,'#76a45c');for(let i=0;i<p.w/11;i++){let x=p.x+i*11;rect(x,p.y-8-hash(i+5)*4,2,7,'#87af62');if(i%4===0)rect(x+2,p.y+3,4,6,'#56834b');if(i%13===0)flower(x,p.y-6,i)}if(!ground){for(let i=0;i<p.w/85;i++){let x=p.x+15+i*85;rect(x,p.y+depth+3,3,10+hash(i)*16,'#5a8250');rect(x-4,p.y+depth+10,5,3,'#79a361')}}}
function ladderDraw(l){rect(l.x-10,l.top-3,4,l.bottom-l.top+3,'#735e43');rect(l.x+7,l.top-3,4,l.bottom-l.top+3,'#735e43');rect(l.x-9,l.top-3,2,l.bottom-l.top+3,'#b39a66');rect(l.x+8,l.top-3,2,l.bottom-l.top+3,'#b39a66');for(let y=l.top+7;y<l.bottom;y+=13){rect(l.x-8,y,17,4,'#b6a273');rect(l.x-8,y+3,17,2,'#776147')}}
function portal(x,y=420){const pulse=.75+Math.sin(time*3)*.15;ctx.save();ctx.globalAlpha=.28;ellipse(x,y-46,34,56,'#8174ff');ctx.globalAlpha=.42;ellipse(x,y-45,25,52,'#b599ff');ctx.globalAlpha=pulse;ellipse(x,y-45,15,48,'#e3b6ff');ctx.globalAlpha=.9;ellipse(x,y-45,6,43,'#f5edff');ellipse(x,y-2,29,6,'#a396ff');ellipse(x,y-3,18,3,'#f7dcff');for(let i=0;i<10;i++){const yy=y-8-((time*29+i*11)%100),xx=x+Math.sin(time*2+i)*23;rect(xx,yy,3,5,i%2?'#eeccff':'#c7edff')}ctx.globalAlpha=.9;for(let i=0;i<5;i++){const yy=y-18-i*16,xx=x+Math.sin(time*2+i*1.3)*5;rect(xx-5,yy,10,2,'#d3c5ff');rect(xx-5,yy-5,2,6,'#f2e7ff');rect(xx+3,yy-1,2,5,'#f2e7ff')}ctx.restore()}

function drawSlime(m){let bounce=Math.sin(time*4+m.phase),squish=1+bounce*.06;ctx.save();ctx.translate(Math.round(m.x),Math.round(m.y));ellipse(0,-1,16,4,'#254b3b44');ctx.scale(1/squish,squish);let c=m.hit>0?'#f4f7cf':'#8fbe7a';rect(-14,-17,28,14,'#385e46');rect(-11,-24,22,21,'#385e46');rect(-7,-28,14,22,'#385e46');rect(-11,-17,22,13,c);rect(-8,-23,16,20,c);rect(-4,-26,8,18,c);rect(-10,-7,21,4,'#689961');rect(-5,-23,7,4,'#c9dea0');rect(-6,-14,3,4,'#2b4939');rect(5,-14,3,4,'#2b4939');rect(0,-8,3,2,'#42694a');rect(-10,-9,4,2,'#deb08a');rect(9,-9,3,2,'#deb08a');ctx.restore();if(m.hp<m.max){rect(m.x-17,m.y-38,34,4,'#294b3d');rect(m.x-16,m.y-37,32*m.hp/m.max,2,'#b1d487')}}
function drawPlayer(actor=player){let x=Math.round(actor.x),y=Math.round(actor.y),walk=actor.ground&&Math.abs(actor.vx)>0?Math.sin(time*13)*3:0;if(actor.invuln>0&&Math.floor(time*14)%2===0)return;ctx.save();ctx.translate(x,y);ellipse(0,-1,15,4,'#28473844');if(actor.haste>0){for(let i=1;i<=3;i++){ctx.globalAlpha=.2/i;rect(-actor.face*i*12-7,-28,15,22,'#def2aa')}ctx.globalAlpha=1}ctx.scale(actor.face,1);rect(-9,-14,7,10+walk,'#514d42');rect(3,-14,7,10-walk,'#514d42');rect(-11,-5+walk,10,5,'#735744');rect(3,-5-walk,11,5,'#735744');rect(-11,-30,23,20,'#344e43');rect(-9,-28,19,17,'#e0d2a2');rect(-8,-27,6,14,'#849b79');rect(5,-27,5,13,'#b5b48c');rect(-10,-14,22,4,'#75664b');rect(-1,-14,4,4,'#e3bf72');rect(-14,-25,5,12,'#e9bc92');rect(10,-25,5,12,'#e9bc92');rect(-9,-47,22,19,'#624e3e');rect(-10,-42,24,13,'#ecc29b');rect(-6,-46,19,17,'#f2ccaa');rect(8,-39,3,4,'#424439');rect(10,-33,4,2,'#d99b87');rect(-10,-50,21,9,'#644a39');rect(-12,-45,8,13,'#74543b');rect(-7,-52,16,5,'#76563c');rect(-4,-48,7,7,'#886849');rect(3,-45,7,3,'#624a37');rect(-7,-54,20,4,'#557351');rect(-9,-51,24,4,'#658b5c');rect(5,-58,3,6,'#d4c187');rect(7,-59,5,3,'#a3b572');
// Wooden shield in the near hand; one-handed sword in the other.
if(!['greatsword','spearman'].includes(actor.job)){poly([[-16,-27],[-5,-29],[0,-24],[-2,-12],[-10,-6],[-17,-13]],'#4c5140');poly([[-14,-25],[-6,-26],[-2,-22],[-4,-14],[-10,-9],[-14,-14]],'#aa9262');rect(-11,-24,2,13,'#cfb677');rect(-15,-19,12,3,'#607362');rect(-10,-20,3,5,'#d3c293');}ctx.save();ctx.translate(13,-21);ctx.rotate(actor.swing>0?-1.6+(.25-actor.swing)*12:.4);if(actor.job==='spearman'){rect(-2,-50,4,70,'#b39862');poly([[-6,-50],[0,-65],[6,-50]],'#dce8d0');}else{if(actor.job==='greatsword')ctx.scale(1.6,1.35);rect(-2,-29,4,26,'#657e78');rect(-1,-29,2,25,'#e6ebd5');poly([[-2,-29],[0,-34],[2,-29]],'#e4ebd9');rect(-6,-5,12,3,'#cdb273');rect(-1,-2,3,9,'#6c4d36');rect(-2,6,5,3,'#bba575');}ctx.restore();ctx.restore();
if(actor.swing>0){ctx.save();ctx.translate(x,y-23);ctx.scale(actor.face,1);ctx.globalAlpha=actor.swing/.25;poly([[22,-43],[62,-33],[80,-7],[77,12],[57,28],[64,5],[55,-15]],'#fff2b7');poly([[58,-24],[83,-1],[75,16],[75,-1]],'#ffffe5');ctx.restore()}ctx.textAlign='center';ctx.font='10px monospace';const label=actor.name||'Fern';const labelWidth=Math.max(36,ctx.measureText(label).width+10);rect(x-labelWidth/2,y+6,labelWidth,14,'#304c3fbb');ctx.fillStyle='#eee9c9';ctx.fillText(label,x,y+16)}
// Original tile art: a pass-through cliff face, with collision only on the grassy ledge.
let cliffPatterns={};
function getCliffPattern(ground=false){const key=ground?'ground':'cliff';if(cliffPatterns[key])return cliffPatterns[key];const tile=document.createElement('canvas');tile.width=128;tile.height=128;const g=tile.getContext('2d');g.fillStyle=ground?'#493b2a':'#73815b';g.fillRect(0,0,128,128);const palette=ground?['#816144','#74563b','#94744f','#886a46','#665035']:['#b0b38a','#a3ad7d','#96a474','#bcc197','#8f9f70'];for(let row=-1;row<8;row++)for(let col=-1;col<8;col++){const seed=row*91+col*17,x=col*21+(row%2)*10,y=row*21,w=16+hash(seed+2)*7,h=17+hash(seed+3)*8;g.fillStyle=palette[Math.floor(hash(seed+7)*palette.length)];g.beginPath();g.moveTo(x+5,y);g.lineTo(x+w-3,y+2);g.lineTo(x+w,y+9);g.lineTo(x+w-4,y+h);g.lineTo(x+3,y+h-2);g.lineTo(x,y+9);g.closePath();g.fill();g.fillStyle=ground?'#b28a5f':'#d3d0aa';g.fillRect(x+5,y+2,Math.max(3,w-10),2);g.fillStyle=ground?'#463626':'#68774f';g.fillRect(x+w-4,y+8,3,Math.max(4,h-9));g.fillStyle=ground?'#a58155':'#b9bf93';g.fillRect(x+3,y+5,2,8);if(hash(seed+15)>.58){g.fillStyle=ground?'#685d38':'#849960';g.fillRect(x+5,y+10,6,3);g.fillRect(x+7,y+12,3,6)}}cliffPatterns[key]=ctx.createPattern(tile,'repeat');return cliffPatterns[key]}
function cliffFace(points,ground=false){ctx.save();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.clip();ctx.fillStyle=getCliffPattern(ground);ctx.fillRect(0,0,worldWidth(),H);ctx.restore()}
function cliffPlatform(p,ground=false){cliffFace([[p.x,p.y],[p.x+p.w,p.y],[p.x+p.w,H],[p.x,H]],ground);rect(p.x,p.y+8,4,H-p.y,'#343f2c55');rect(p.x+p.w-5,p.y+8,5,H-p.y,'#283a2566')}
function grassEdge(x,y,w){rect(x,y,w,7,'#2b6035');rect(x,y-3,w,4,'#6a9a4e');rect(x,y-5,w,2,'#adc16b');for(let n=0;n<w/7;n++){const px=x+n*7,k=hash(n+x);rect(px,y-7-k*5,2,8,'#75a453');if(n%3===0){rect(px+2,y+3,3,5+k*7,'#496f36');rect(px+3,y-5,2,5,'#b4c97a')}if(n%9===0){rect(px,y+8,2,6,'#7c8c40')}}}
function mushroom(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);rect(-2,-13,5,13,'#d9d0a2');rect(-3,-6,2,6,'#a79b71');rect(-10,-16,21,6,'#704930');rect(-9,-20,18,6,'#c89349');rect(-5,-23,11,5,'#e0b768');rect(-5,-20,3,3,'#f5dfad');rect(4,-17,3,2,'#f5dfad');ctx.restore()}
function drawTerrain(){const town=player.map==='town';if(town){cliffFace([[0,290],[380,290],[680,420],[0,420]]);cliffPlatform(platforms[2]);grassEdge(0,290,380);for(let x=380;x<680;x+=4){const y=290+(x-380)/300*130;rect(x,y-4,5,7,'#689348');rect(x,y-5,5,2,'#acc375');if(x%12===0)rect(x,y-9,2,6,'#80ad58')}grassEdge(platforms[2].x,platforms[2].y,platforms[2].w);mushroom(30,288,.85);mushroom(355,288,.6);mushroom(846,168,1);mushroom(881,168,.7)}else{for(const p of platforms.slice(1))cliffPlatform(p);for(const p of platforms.slice(1)){grassEdge(p.x,p.y,p.w);mushroom(p.x+36,p.y-2,.8);mushroom(p.x+p.w-35,p.y-2,.6)}}cliffPlatform(platforms[0],true);rect(0,428,worldWidth(),4,'#4e3c2c');grassEdge(0,420,worldWidth());mushroom(worldWidth()-45,418,1.1);mushroom(worldWidth()-72,418,.6)}
